// Served at blogs.yashsiwach.in/robots.txt (see rewrites in next.config.js).
// The main site's robots.txt is generated by next-sitemap and names the www host.
export function GET() {
  return new Response(
    'User-agent: *\nAllow: /\n\nSitemap: https://blogs.yashsiwach.in/sitemap.xml\n',
    { headers: { 'Content-Type': 'text/plain' } }
  );
}
